package com.andye.warmod.block.entity;import com.andye.warmod.block.*;import com.andye.warmod.radar.display.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.core.UUIDUtil;import net.minecraft.network.protocol.*;import net.minecraft.network.protocol.game.*;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.storage.*;import org.jspecify.annotations.Nullable;
public final class RadarDisplayPanelBlockEntity extends BlockEntity{private @Nullable UUID displayId;private BlockPos controller;private int size;private boolean valid;private @Nullable RadarDisplayLink link;public RadarDisplayPanelBlockEntity(BlockPos p,BlockState s){super(ModBlockEntities.RADAR_DISPLAY_PANEL,p,s);controller=p;}public void configure(@Nullable UUID id,BlockPos controller,int size,boolean valid,@Nullable RadarDisplayLink common){displayId=id;this.controller=controller;this.size=size;this.valid=valid;if(common!=null)link=common;sync();}public void link(RadarDisplayLink value){link=value;sync();}public @Nullable RadarDisplayLink link(){return link;}public @Nullable UUID displayId(){return displayId;}public BlockPos controller(){return controller;}public int size(){return size;}public int radius(){return valid?RadarDisplayConstants.radius(size):0;}public boolean valid(){return valid;}public boolean controllerPanel(){return valid&&worldPosition.equals(controller);}@Override protected void saveAdditional(ValueOutput o){super.saveAdditional(o);o.storeNullable("display_id",UUIDUtil.CODEC,displayId);o.store("controller",BlockPos.CODEC,controller);o.putInt("size",size);o.putBoolean("valid",valid);if(link!=null)o.store("link",RadarDisplayLink.CODEC,link);}@Override protected void loadAdditional(ValueInput i){super.loadAdditional(i);displayId=i.read("display_id",UUIDUtil.CODEC).orElse(null);controller=i.read("controller",BlockPos.CODEC).orElse(worldPosition);size=i.getIntOr("size",0);valid=i.getBooleanOr("valid",false);link=i.read("link",RadarDisplayLink.CODEC).orElse(null);}private void sync(){setChanged();if(level!=null)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}@Override public @Nullable Packet<ClientGamePacketListener> getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public net.minecraft.nbt.CompoundTag getUpdateTag(net.minecraft.core.HolderLookup.Provider r){return saveCustomOnly(r);}}
